<script setup>
import { onMounted, ref } from 'vue'
import ReportExportActions from './ReportExportActions.vue'
import { apiOrigin } from '../services/auth.js'
const props = defineProps({ session: { type: Object, required: true } })
const parts = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())
const datePart = name => parts.find(x => x.type === name).value
const today = `${datePart('year')}-${datePart('month')}-${datePart('day')}`
const from = ref(today.slice(0, 7) + '-01'), to = ref(today), partner = ref(''), branch = ref(''), options = ref({ partners: [], branches: [] }), data = ref(null), applied = ref(null), busy = ref(false), error = ref('')
const money = x => x == null ? 'Не визначено' : Number(x).toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
async function api(path) { const response = await fetch(`${apiOrigin}/api/reports/partner-results${path}`, { headers: { Authorization: `Bearer ${props.session.token}` } }); const result = await response.json().catch(() => null); if (!response.ok) throw new Error(result?.message || `Не вдалося завантажити звіт (HTTP ${response.status})`); return result }
async function load(page = 0, filters = null) { if (busy.value) return; const f = filters || applied.value; if (!f?.from || !f?.to || f.from > f.to) { error.value = 'Перевірте період.'; return } busy.value = true; error.value = ''; data.value = null; try { const query = new URLSearchParams({ from: f.from, to: f.to, page: String(page) }); if (f.partner) query.set('partner', f.partner); if (f.branch) query.set('branch', f.branch); data.value = await api('?' + query); applied.value = { ...f } } catch (e) { error.value = e.message } finally { busy.value = false } }
function apply() { return load(0, { from: from.value, to: to.value, partner: partner.value, branch: branch.value }) }
onMounted(async () => { try { options.value = await api('/options'); await apply() } catch (e) { error.value = e.message } })
</script>
<template>
 <section class="partner-results"><h1>Результати роботи з посередниками</h1><p>Оборот за первісними рахунками. Об’єднання залишків боргу не створює повторного продажу.</p>
  <form @submit.prevent="apply"><label>Від<input v-model="from" type="date" required :disabled="busy"></label><label>До включно<input v-model="to" type="date" required :disabled="busy"></label><label>Фірма<select v-model="partner" :disabled="busy"><option value="">Усі фірми</option><option v-for="p in options.partners" :key="p.id" :value="String(p.id)">{{ p.name }}</option></select></label><label>Філія (оборот)<select v-model="branch" :disabled="busy"><option value="">Усі філії</option><option v-for="b in options.branches" :key="b.id" :value="String(b.id)">{{ b.name }}</option></select></label><button :disabled="busy">Показати</button></form>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="busy">Формування звіту…</p>
  <template v-if="data"><ReportExportActions :session="session" kind="partner" :filters="applied" :disabled="busy" /><p>{{ data.from }} — {{ data.to }} · {{ options.partners.find(p => String(p.id) === applied.partner)?.name || 'Усі фірми' }} · {{ options.branches.find(b => String(b.id) === applied.branch)?.name || 'Усі філії' }}. Підсумки за всіма сторінками.</p>
   <div class="metrics"><article>Первісних рахунків<strong>{{ data.summary.invoiceCount }}</strong><small>Позицій виробів: {{ data.summary.productCount }}</small></article><article>Виставлено, грн<strong>{{ money(data.summary.knownSales) }}</strong></article><article>{{ data.summary.unknownMaterials ? 'Матеріали: відома частина, грн' : 'Матеріали, грн' }}<strong>{{ money(data.summary.knownMaterials) }}</strong></article><article>Різниця, грн<strong>{{ money(data.summary.difference) }}</strong></article></div>
   <p v-if="data.summary.incompleteCount" class="warning">Неповна собівартість для {{ data.summary.incompleteCount }} позицій. Різниця лише за повністю оціненими: {{ money(data.summary.completeDifference) }} грн.</p>
   <details><summary>Правила розрахунку</summary><p>Суми — з первісних реселлерських рахунків за датою створення (період Europe/Kyiv), включно з рахунками, які пізніше об’єднали. Чернетки, скасовані рахунки та рядки перенесення боргу виключено. При фільтрі філії показано лише її позиції рахунків.</p><p>Матеріали — за зафіксованою вартістю виробничих списань, включно з доопрацюваннями. Старі невідомі ціни не замінюються поточними. Різниця не є чистим прибутком: роботи, зарплата, оренда та інші накладні не віднімаються.</p><p>Історичні рахунки без зафіксованої фірми-посередника або без складу виробів у оборот не включено. Це звіт за чинним станом документів, без закриття періодів і автоматичного обліку повернень.</p></details>
   <section class="debt"><h3>Поточний борг за рахунками: {{ money(data.debtTotal) }} грн</h3><p>За всіма чинними рахунками вибраної фірми або всіх фірм. Період та філія вище не обмежують цей борг. Незараховані аванси не віднімаються; це не чистий баланс клієнта.</p><p v-for="d in data.debts" :key="d.partnerId">{{ d.partnerName }}: <strong>{{ money(d.debt) }} грн</strong></p></section>
   <p v-if="!data.rows.length">За вибраними умовами первісних рахунків немає.</p>
   <article v-for="row in data.rows" :key="`${row.invoiceId}-${row.productId}`" class="line"><strong>{{ row.partnerName }} · {{ row.branchName }}</strong><p>Рахунок № {{ row.invoiceNo }} · {{ row.invoicedAt }}</p><p>Замовлення № {{ row.orderNo }} · {{ row.productName }}</p><dl><div><dt>Виставлено</dt><dd>{{ money(row.saleAmount) }}</dd></div><div><dt>{{ row.unknownMaterials ? 'Матеріали (частково)' : 'Матеріали' }}</dt><dd>{{ money(row.materialAmount) }}</dd></div><div><dt>Різниця</dt><dd>{{ money(row.difference) }}</dd></div></dl><small v-if="row.unknownMaterials">Неоцінених позицій матеріалу: {{ row.unknownMaterials }}</small></article>
   <div class="paging"><button :disabled="busy || !data.page" @click="load(data.page - 1)">Назад</button><span>Сторінка {{ data.page + 1 }}</span><button :disabled="busy || !data.hasMore" @click="load(data.page + 1)">Далі</button></div>
  </template>
 </section>
</template>
<style scoped>
.partner-results{max-width:1250px;margin:auto;padding:20px;min-width:0;color:#233442}.partner-results form{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:20px 0}.partner-results label{display:grid;gap:6px;min-width:0;flex:1 1 170px}.partner-results input,.partner-results select,.partner-results button{font:inherit;min-height:44px;box-sizing:border-box;padding:10px;border:1px solid #bdccd4;border-radius:7px;max-width:100%;min-width:0}.partner-results button{background:#185c63;color:#fff;cursor:pointer}.partner-results button:disabled{opacity:.5}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metrics article,.debt{padding:16px;background:#eef5f6;border-radius:10px}.metrics strong{display:block;font-size:22px;margin:10px 0}.metrics small{display:block}.partner-results p{line-height:1.5}.partner-results details,.debt{margin:18px 0}.partner-results summary{cursor:pointer}.line{border:1px solid #dce4e9;border-radius:10px;padding:14px;margin:12px 0;overflow-wrap:anywhere}.line dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.line dd{margin:6px 0;font-weight:bold}.paging{display:flex;align-items:center;gap:12px}.warning{padding:12px;background:#fff4d5}[role=alert]{color:#a22}@media(max-width:700px){.partner-results{padding:12px}.metrics{grid-template-columns:1fr 1fr}.line dl{grid-template-columns:1fr}.partner-results form button{width:100%}}
</style>
